    // Helper to compress uploaded images using canvas to prevent localStorage quota overflow
    function compressImage(file, maxWidth, maxHeight, quality = 0.8) {
        return new Promise((resolve, reject) => {
            if (!file) {
                resolve(null);
                return;
            }
            const reader = new FileReader();
            reader.onload = (event) => {
                const img = new Image();
                img.onload = () => {
                    const canvas = document.createElement('canvas');
                    let width = img.width;
                    let height = img.height;

                    if (width > height) {
                        if (width > maxWidth) {
                            height = Math.round((height * maxWidth) / width);
                            width = maxWidth;
                        }
                    } else {
                        if (height > maxHeight) {
                            width = Math.round((width * maxHeight) / height);
                            height = maxHeight;
                        }
                    }

                    canvas.width = width;
                    canvas.height = height;

                    const ctx = canvas.getContext('2d');
                    ctx.drawImage(img, 0, 0, width, height);

                    const compressedDataUrl = canvas.toDataURL('image/jpeg', quality);
                    resolve(compressedDataUrl);
                };
                img.onerror = (err) => reject(err);
                img.src = event.target.result;
            };
            reader.onerror = (err) => reject(err);
            reader.readAsDataURL(file);
        });
    }

    // Dynamic Scaling logic to fit preview A4 container to screen
    function adjustScale() {
        const viewport = document.querySelector('.preview-viewport');
        const container = document.querySelector('.a4-container');
        if (!viewport || !container) return;

        const isLandscape = container.classList.contains('landscape');
        const targetWidth = isLandscape ? 1122.5 : 793.7; // 297mm vs 210mm in pixels at 96dpi
        const targetHeight = isLandscape ? 793.7 : 1122.5; // 210mm vs 297mm in pixels at 96dpi

        const viewWidth = viewport.clientWidth - 40; // 20px padding left/right
        const viewHeight = viewport.clientHeight - 40; // 20px padding top/bottom

        const scaleX = viewWidth / targetWidth;
        const scaleY = viewHeight / targetHeight;
        
        const scale = Math.min(scaleX, scaleY);
        const finalScale = Math.max(0.1, Math.min(scale, 1.0)); // Cap scaling at 100%

        container.style.transform = `scale(${finalScale})`;
        container.style.transformOrigin = 'center center';
    }

    // Get today's local date string formatted as YYYY-MM-DD
    function getTodayDateString() {
        const d = new Date();
        const year = d.getFullYear();
        const month = String(d.getMonth() + 1).padStart(2, '0');
        const day = String(d.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}`;
    }

    // Helper: Parse YYYY-MM-DD and return day of week name + DD/MM/YYYY date
    function parseAndFormatDate(dateStr) {
        if (!dateStr) return { day: '', date: '' };
        const parts = dateStr.split('-');
        if (parts.length !== 3) return { day: '', date: '' };
        
        const year = parseInt(parts[0], 10);
        const month = parseInt(parts[1], 10) - 1;
        const day = parseInt(parts[2], 10);
        const dateObj = new Date(year, month, day);

        const days = ['SUNDAY', 'MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY'];
        const dayName = days[dateObj.getDay()] || '';
        
        const formattedDay = String(day).padStart(2, '0');
        const formattedMonth = String(month + 1).padStart(2, '0');
        
        return {
            day: dayName,
            date: `${formattedDay}/${formattedMonth}/${year}`
        };
    }

    // Update the Date Elements
    function updateDateDisplay(dateStr, endDateStr) {
        const formattedStart = parseAndFormatDate(dateStr);
        controlDatePicker.value = dateStr;
        hiddenDatePicker.value = dateStr;

        if (controlEndDatePicker) {
            controlEndDatePicker.value = endDateStr || '';
        }

        if (endDateStr) {
            const formattedEnd = parseAndFormatDate(endDateStr);
            headerDayEl.textContent = 'VALID';
            headerDateEl.textContent = `${formattedStart.date} - ${formattedEnd.date}`;
        } else {
            headerDayEl.textContent = formattedStart.day;
            headerDateEl.textContent = formattedStart.date;
        }
    }

