    const savePngBtn = document.getElementById('save-png-btn');
    if (savePngBtn) {
        savePngBtn.addEventListener('click', () => {
            prepareForExport();

            const originalText = savePngBtn.textContent;
            savePngBtn.textContent = 'Generating...';
            savePngBtn.disabled = true;

            const container = document.querySelector('.a4-container');
            const oldTransform = container.style.transform;

            // Temporarily reset transform for clean high-res capturing
            container.style.transform = 'none';

            // Use double requestAnimationFrame to ensure browser has repainted
            requestAnimationFrame(() => {
                requestAnimationFrame(() => {
                    html2canvas(container, {
                        scale: 4, // 4x scale for crisp print-quality rendering
                        useCORS: true,
                        allowTaint: true,
                        backgroundColor: '#ffffff',
                        logging: false,
                        scrollX: 0,
                        scrollY: 0,
                        onclone: (clonedDoc) => {
                            const imageWrappers = clonedDoc.querySelectorAll('.card-image-wrapper');
                            imageWrappers.forEach(wrapper => {
                                wrapper.style.position = 'absolute';
                                wrapper.style.top = '10%';
                                wrapper.style.left = '4%';
                                wrapper.style.width = '92%';
                                wrapper.style.height = '80%';
                                wrapper.style.transform = 'none';
                                wrapper.style.webkitTransform = 'none';
                            });
                        }
                    }).then(canvas => {
                        // Restore original scale/transform
                        container.style.transform = oldTransform;

                        // Restore button state
                        savePngBtn.textContent = originalText;
                        savePngBtn.disabled = false;

                        // Download the image
                        const link = document.createElement('a');
                        const sanitizedTitle = headerTitle.trim().replace(/[^a-z0-9]/gi, '_').toLowerCase();
                        link.download = `${sanitizedTitle || 'promo'}_poster.png`;
                        link.href = canvas.toDataURL('image/png');
                        link.click();
                    }).catch(err => {
                        console.error('PNG generation failed:', err);
                        // Restore original state
                        container.style.transform = oldTransform;
                        savePngBtn.textContent = originalText;
                        savePngBtn.disabled = false;
                        alert('Failed to generate PNG image. Please try again.');
                    });
                });
            });
        });
    }
