    // Smart File Parser for CSV and Excel
    function parseProductFile(file) {
        const reader = new FileReader();
        reader.onload = function (e) {
            try {
                const data = new Uint8Array(e.target.result);
                const workbook = XLSX.read(data, { type: 'array' });
                const firstSheetName = workbook.SheetNames[0];
                const worksheet = workbook.Sheets[firstSheetName];
                const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1 });
                
                if (!jsonData || jsonData.length === 0) {
                    alert('The file seems to be empty.');
                    return;
                }

                // Smart Header Mapping
                const headers = jsonData[0].map(h => String(h || '').toLowerCase().trim());
                
                let nameIndex = -1;
                let unitIndex = -1;
                let mrpIndex = -1;
                let spIndex = -1;
                let imgIndex = -1;

                // Match fields
                nameIndex = headers.findIndex(h => h.includes('name') || h.includes('product') || h.includes('item') || h.includes('title') || h.includes('desc'));
                unitIndex = headers.findIndex(h => h.includes('unit') || h.includes('weight') || h.includes('qty') || h.includes('pack') || h.includes('measure') || h.includes('size') || h.includes('kg'));
                mrpIndex = headers.findIndex(h => h.includes('mrp') || h.includes('market') || h.includes('original') || h.includes('old') || h.includes('cross') || h.includes('strike') || h.includes('list') || h.includes('retail'));
                spIndex = headers.findIndex(h => h.includes('selling') || h.includes('sp') || h.includes('offer') || h.includes('promo') || h.includes('sale') || h.includes('price') || h.includes('special') || h.includes('new') || h.includes('discount') || h.includes('rate'));
                imgIndex = headers.findIndex(h => h.includes('image') || h.includes('img') || h.includes('pic') || h.includes('photo') || h.includes('url'));

                // Fallbacks
                if (nameIndex === -1 && headers.length > 0) nameIndex = 0;
                if (spIndex === -1 && headers.length > 1) spIndex = 1;
                if (mrpIndex === -1 && headers.length > 2) mrpIndex = 2;
                if (unitIndex === -1 && headers.length > 3) unitIndex = 3;

                const parsed = [];
                for (let r = 1; r < jsonData.length; r++) {
                    const row = jsonData[r];
                    if (!row || row.length === 0) continue;

                    const nameVal = nameIndex !== -1 ? String(row[nameIndex] || '').trim().toUpperCase() : '';
                    const spVal = spIndex !== -1 ? String(row[spIndex] || '').trim() : '';
                    
                    if (!nameVal && !spVal) continue;

                    const unitVal = unitIndex !== -1 ? String(row[unitIndex] || '').trim() : 'KG';
                    const mrpVal = mrpIndex !== -1 ? String(row[mrpIndex] || '').trim() : '';
                    
    // Helper to convert Google Drive sharing/view links into direct image URLs
    function convertGoogleDriveUrl(url) {
        if (!url) return url;
        let fileId = null;
        const driveMatch1 = url.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
        const driveMatch2 = url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
        if (driveMatch1 && driveMatch1[1]) {
            fileId = driveMatch1[1];
        } else if (driveMatch2 && driveMatch2[1]) {
            fileId = driveMatch2[1];
        }
        if (fileId) {
            return `https://lh3.googleusercontent.com/d/${fileId}`;
        }
        return url;
    }

                    let imgVal = null;
                    if (imgIndex !== -1 && row[imgIndex]) {
                        const rawImg = String(row[imgIndex]).trim();
                        if (rawImg.startsWith('http://') || rawImg.startsWith('https://') || rawImg.startsWith('data:')) {
                            imgVal = convertGoogleDriveUrl(rawImg);
                        } else if (rawImg.startsWith('images/')) {
                            imgVal = rawImg;
                        } else {
                            imgVal = 'images/' + rawImg;
                        }
                    }

                    parsed.push({
                        id: 'db_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
                        name: nameVal,
                        unit: unitVal || 'KG',
                        mrp: mrpVal,
                        sellingPrice: spVal,
                        image: imgVal
                    });
                }

                if (parsed.length === 0) {
                    alert('No valid product rows could be imported. Please verify file format.');
                    return;
                }

                importedProducts = parsed;
                localStorage.setItem('supermarket_imported_products', JSON.stringify(importedProducts));
                renderProductDatabase();
                if (typeof renderSpreadsheetTable === 'function') {
                    renderSpreadsheetTable(document.getElementById('ss-search-input') ? document.getElementById('ss-search-input').value : '');
                }

                // Auto-fill active slots with imported products
                const limit = getActiveSlotsCount();
                for (let i = 0; i < Math.min(limit, importedProducts.length); i++) {
                    const p = importedProducts[i];
                    items[i] = {
                        id: i,
                        name: p.name,
                        unit: p.unit,
                        mrp: p.mrp,
                        sellingPrice: p.sellingPrice,
                        image: p.image || null
                    };
                }
                saveItems();
                renderGrid();
                alert(`Successfully imported ${importedProducts.length} products! The poster has been auto-populated with the first ${Math.min(limit, importedProducts.length)} items.`);
            } catch (err) {
                console.error(err);
                alert('Failed to parse file: ' + err.message);
            }
        };
        reader.readAsArrayBuffer(file);
    }

    // Render Product List in Sidebar
    function renderProductDatabase(filterQuery = '') {
        if (!sidebarProductList) return;
        sidebarProductList.innerHTML = '';

        const query = filterQuery.toLowerCase().trim();
        const filtered = importedProducts.filter(p => 
            p.name.toLowerCase().includes(query) || 
            (p.sellingPrice && p.sellingPrice.toString().includes(query))
        );

        if (filtered.length === 0) {
            sidebarProductList.innerHTML = `
                <div class="empty-list-msg">
                    ${query ? 'No matching products found.' : 'No products loaded. Import Excel/CSV or add products manually.'}
                </div>
            `;
            return;
        }

        filtered.forEach((product) => {
            const row = document.createElement('div');
            row.className = 'product-item-row';
            row.draggable = true;

            let metaHtml = `₹${product.sellingPrice || '0.00'}`;
            if (product.unit) metaHtml += ` / ${product.unit}`;
            if (product.mrp && parseFloat(product.mrp) > parseFloat(product.sellingPrice)) {
                metaHtml += ` <span class="mrp-meta">MRP ₹${product.mrp}</span>`;
            }

            row.innerHTML = `
                <div class="item-info">
                    <div class="item-name">${product.name}</div>
                    <div class="item-meta">${metaHtml}</div>
                </div>
                <div class="item-actions">
                    <button class="action-btn assign-btn" title="Assign to slot">🎯</button>
                    <button class="action-btn edit-btn" title="Edit product">✏️</button>
                    <button class="action-btn delete-btn" title="Delete product">🗑️</button>
                </div>
            `;

            // HTML5 Drag Event for dragging items to grid
            row.addEventListener('dragstart', (e) => {
                e.dataTransfer.setData('text/plain', JSON.stringify(product));
                row.classList.add('dragging');
            });

            row.addEventListener('dragend', () => {
                row.classList.remove('dragging');
            });

            // Assign to Slot button
            row.querySelector('.assign-btn').addEventListener('click', (e) => {
                e.stopPropagation();
                const slotsCount = getActiveSlotsCount();
                const slotStr = prompt(`Enter Slot Number to assign (1 to ${slotsCount}):`, "1");
                if (slotStr) {
                    const slotIdx = parseInt(slotStr, 10) - 1;
                    if (slotIdx >= 0 && slotIdx < slotsCount) {
                        items[slotIdx] = {
                            id: slotIdx,
                            name: product.name,
                            unit: product.unit,
                            mrp: product.mrp,
                            sellingPrice: product.sellingPrice,
                            image: product.image || null
                        };
                        saveItems();
                        renderGrid();
                    } else {
                        alert(`Invalid slot. Please enter a number between 1 and ${slotsCount}.`);
                    }
                }
            });

            // Edit product button
            row.querySelector('.edit-btn').addEventListener('click', (e) => {
                e.stopPropagation();
                openDbEditor(product.id);
            });

            // Delete product button
            row.querySelector('.delete-btn').addEventListener('click', (e) => {
                e.stopPropagation();
                if (confirm(`Are you sure you want to delete "${product.name}"?`)) {
                    importedProducts = importedProducts.filter(p => p.id !== product.id);
                    localStorage.setItem('supermarket_imported_products', JSON.stringify(importedProducts));
                    renderProductDatabase(productSearchInput.value);
                }
            });

            sidebarProductList.appendChild(row);
        });
    }

    function getActiveSlotsCount() {
        let limit = 12;
        if (activeLayout === '2-landscape') limit = 2;
        else if (activeLayout === '3-landscape') limit = 3;
        else if (activeLayout === '6-landscape') limit = 6;
        else if (activeLayout === '8-landscape') limit = 8;
        else if (activeLayout === '12-landscape') limit = 12;
        else if (activeLayout === '16-landscape') limit = 16;
        else if (activeLayout === '18') limit = 18;
        else limit = parseInt(activeLayout, 10) || 12;
        return limit;
    }

