    // Render spreadsheet table
    window.renderSpreadsheetTable = function(filterQuery = '') {
        if (!ssTableBody) return;
        ssTableBody.innerHTML = '';

        const query = filterQuery.toLowerCase().trim();
        const filtered = importedProducts.filter(p => 
            (p.name || '').toLowerCase().includes(query) || 
            (p.sellingPrice && p.sellingPrice.toString().includes(query)) ||
            (p.unit || '').toLowerCase().includes(query)
        );

        if (ssRowCount) {
            ssRowCount.textContent = `${filtered.length} products found (Total: ${importedProducts.length})`;
        }

        if (filtered.length === 0) {
            ssTableBody.innerHTML = `
                <tr>
                    <td colspan="7" style="text-align: center; color: #64748b; padding: 20px;">
                        No matching products. Click "Add New Row" to create one or drag/drop an Excel/CSV file to load data.
                    </td>
                </tr>
            `;
            return;
        }

        filtered.forEach((product, idx) => {
            const tr = document.createElement('tr');

            // Find index of this item in the global importedProducts list
            const globalIdx = importedProducts.findIndex(p => p.id === product.id);

            // Thumbnail visual element
            const imageSrc = product.image || '';
            const imgHtml = imageSrc ? `<img class="ss-thumb" src="${imageSrc}">` : '<div class="ss-thumb" style="display:flex;align-items:center;justify-content:center;font-size:10px;color:#94a3b8;">N/A</div>';

            tr.innerHTML = `
                <td style="text-align: center; color: #64748b; font-weight: 500;">${globalIdx + 1}</td>
                <td><input type="text" class="ss-input-name" value="${product.name || ''}" placeholder="e.g. ONION"></td>
                <td><input type="text" class="ss-input-unit" value="${product.unit || 'KG'}" placeholder="e.g. KG"></td>
                <td><input type="number" step="0.01" class="ss-input-mrp" value="${product.mrp || ''}" placeholder="e.g. 25.00"></td>
                <td><input type="number" step="0.01" class="ss-input-sp" value="${product.sellingPrice || ''}" placeholder="e.g. 19.90"></td>
                <td>
                    <div class="ss-thumbnail-cell">
                        ${imgHtml}
                        <input type="text" class="ss-input-image" value="${product.image || ''}" placeholder="e.g. images/onion.jpg or url" style="flex: 1;">
                    </div>
                </td>
                <td style="text-align: center;">
                    <button class="ss-delete-row-btn" title="Delete product">🗑️</button>
                </td>
            `;

            // Event listeners to update changes instantly in memory
            const nameInput = tr.querySelector('.ss-input-name');
            const unitInput = tr.querySelector('.ss-input-unit');
            const mrpInput = tr.querySelector('.ss-input-mrp');
            const spInput = tr.querySelector('.ss-input-sp');
            const imgInput = tr.querySelector('.ss-input-image');
            const deleteRowBtn = tr.querySelector('.ss-delete-row-btn');

            nameInput.addEventListener('input', (e) => {
                const upperVal = e.target.value.toUpperCase();
                e.target.value = upperVal;
                importedProducts[globalIdx].name = upperVal;
            });

            unitInput.addEventListener('input', (e) => {
                importedProducts[globalIdx].unit = e.target.value;
            });

            mrpInput.addEventListener('input', (e) => {
                importedProducts[globalIdx].mrp = e.target.value;
            });

            spInput.addEventListener('input', (e) => {
                importedProducts[globalIdx].sellingPrice = e.target.value;
            });

            imgInput.addEventListener('input', (e) => {
                const newVal = e.target.value.trim();
                importedProducts[globalIdx].image = newVal || null;
                // Live thumbnail preview update
                const thumbCell = tr.querySelector('.ss-thumbnail-cell');
                const existingThumb = thumbCell.querySelector('.ss-thumb') || thumbCell.querySelector('div.ss-thumb');
                if (newVal) {
                    const newImg = document.createElement('img');
                    newImg.className = 'ss-thumb';
                    newImg.src = newVal;
                    newImg.onerror = () => {
                        newImg.style.display = 'none';
                    };
                    if (existingThumb) existingThumb.replaceWith(newImg);
                } else {
                    const fallbackDiv = document.createElement('div');
                    fallbackDiv.className = 'ss-thumb';
                    fallbackDiv.style.cssText = 'display:flex;align-items:center;justify-content:center;font-size:10px;color:#94a3b8;';
                    fallbackDiv.textContent = 'N/A';
                    if (existingThumb) existingThumb.replaceWith(fallbackDiv);
                }
            });

            deleteRowBtn.addEventListener('click', () => {
                if (confirm(`Are you sure you want to delete "${product.name || 'this item'}"?`)) {
                    importedProducts.splice(globalIdx, 1);
                    renderSpreadsheetTable(ssSearchInput ? ssSearchInput.value : '');
                }
            });

            ssTableBody.appendChild(tr);
        });
    }
