    // Smart Multi-Tier Image Matcher Helper
    function findMatchingImageFile(productName, imageFiles) {
        if (!productName || !imageFiles || imageFiles.length === 0) return null;

        const normProduct = productName.trim().toUpperCase();
        const cleanProduct = normProduct.replace(/[^A-Z0-9\s]/g, '').trim();
        if (!cleanProduct) return null;

        const productWords = cleanProduct.split(/\s+/).filter(w => w.length > 1);

        // 1. Exact match
        for (let file of imageFiles) {
            const fileBase = file.name.replace(/\.[^/.]+$/, "").trim().toUpperCase();
            if (fileBase === normProduct) return file;
        }

        // 2. Cleaned alphanumeric match (ignoring spaces, dashes, underscores)
        const alphaProduct = cleanProduct.replace(/\s+/g, '');
        for (let file of imageFiles) {
            const fileBase = file.name.replace(/\.[^/.]+$/, "").trim().toUpperCase();
            const alphaFile = fileBase.replace(/[^A-Z0-9]/g, '');
            if (alphaFile && alphaFile === alphaProduct) return file;
        }

        // 3. Substring match (e.g. image "ONION" matching product "FRESH ONION")
        for (let file of imageFiles) {
            const fileBase = file.name.replace(/\.[^/.]+$/, "").trim().toUpperCase();
            const cleanFile = fileBase.replace(/[^A-Z0-9\s]/g, '').trim();
            if (cleanFile.length >= 3 && (cleanProduct.includes(cleanFile) || cleanFile.includes(cleanProduct))) {
                return file;
            }
        }

        // 4. Significant word overlap match
        for (let file of imageFiles) {
            const fileBase = file.name.replace(/\.[^/.]+$/, "").trim().toUpperCase();
            const cleanFile = fileBase.replace(/[^A-Z0-9\s]/g, '').trim();
            const fileWords = cleanFile.split(/\s+/).filter(w => w.length > 2);
            
            for (let pw of productWords) {
                if (pw.length >= 3 && fileWords.includes(pw)) {
                    return file;
                }
            }
        }

        return null;
    }

    if (driveFolderInput) {
        driveFolderInput.addEventListener('change', async function () {
            if (!this.files || this.files.length === 0) return;

            const files = Array.from(this.files);
            // Filter image files by type or extension
            const imageFiles = files.filter(f => f.type.startsWith('image/') || /\.(jpg|jpeg|png|webp|gif|svg)$/i.test(f.name));

            if (imageFiles.length === 0) {
                alert('No image files found in the selected folder.');
                return;
            }

            let matchedDbCount = 0;
            let matchedPosterCount = 0;

            // Match Database products (importedProducts)
            for (let p of importedProducts) {
                const file = findMatchingImageFile(p.name, imageFiles);
                if (file) {
                    try {
                        const compressedDataUrl = await compressImage(file, 1024, 1024, 0.85);
                        if (compressedDataUrl) {
                            p.image = compressedDataUrl;
                            matchedDbCount++;
                        }
                    } catch (err) {
                        console.error(`Failed to load image for ${p.name}`, err);
                    }
                }
            }

            if (matchedDbCount > 0) {
                localStorage.setItem('supermarket_imported_products', JSON.stringify(importedProducts));
                renderProductDatabase();
                if (typeof renderSpreadsheetTable === 'function') {
                    renderSpreadsheetTable(document.getElementById('ss-search-input') ? document.getElementById('ss-search-input').value : '');
                }
            }

            // Match active Poster Items (items)
            for (let item of items) {
                const file = findMatchingImageFile(item.name, imageFiles);
                if (file) {
                    try {
                        const compressedDataUrl = await compressImage(file, 1024, 1024, 0.85);
                        if (compressedDataUrl) {
                            item.image = compressedDataUrl;
                            matchedPosterCount++;
                        }
                    } catch (err) {
                        console.error(`Failed to load poster image for ${item.name}`, err);
                    }
                }
            }

            if (matchedPosterCount > 0) {
                saveItems();
                renderGrid();
            }

            this.value = ''; // Reset file input

            const totalMatched = Math.max(matchedDbCount, matchedPosterCount);
            if (totalMatched > 0) {
                alert(`🎉 Success! Matched ${matchedDbCount} product database entries and ${matchedPosterCount} poster tags with images from the selected folder.`);
            } else {
                alert(`Found ${imageFiles.length} image files, but none matched your product names. Ensure image files are named like "[Product Title].jpeg" or ".png".`);
            }
        });
    }

